(async()=>{
const {filterProducts}=await import('./core.mjs');
const {canOrder,normalizeCart,cartSummary,buildWhatsAppParts}=await import('./cart.mjs');
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={other:'<path d="M3 6h18v15H3zM2 3h20v3H2zM9 10h6"/>',all:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',tablets:'<rect x="6" y="2" width="12" height="20" rx="6" transform="rotate(40 12 12)"/><path d="m7 8 9 8"/>',supplements:'<path d="M8 6V3h8v3M6 9h12v12H6zM8 6h8v3H8zM9 14h6m-3-3v6"/>',liquids:'<path d="M9 3h6v5H9zM9 8 6 12v9h12v-9l-3-4M6 15h12"/>',care:'<path d="M5 3h14l-3 15H8zM8 18h8v4H8zM7 7h10"/>',injections:'<path d="m4 20 4-4m-1-4 5-5 5 5-5 5zM12 7l2-2m3 7 2-2M12 3l9 9M3 21l1-1m5-7 2 2"/>',nutrition:'<path d="M6 4h12v18H6zM6 8h12M8 1h8v3M9 13h6v5H9z"/>'};
const cats={all:'جميع المنتجات',tablets:'أقراص وكبسولات',supplements:'فيتامينات ومكملات',liquids:'شراب وقطرات',care:'كريمات وعناية',injections:'حقن ومشافي',nutrition:'حليب وتغذية',other:'منتجات أخرى'};
const svg=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.tablets}</svg>`;
let data;try{const r=await fetch('data.json');if(!r.ok)throw Error();data=await r.json()}catch(e){$('#resultCount').textContent='تعذّر تحميل القائمة. أعد تحميل الصفحة.';$('#loadMore').hidden=true;return}
const products=data.products;let favorites=[];try{const stored=JSON.parse(localStorage.getItem('asima-favorites')||'[]');if(Array.isArray(stored))favorites=stored.filter(x=>typeof x==='string'&&products.some(p=>p.id===x))}catch{}
let cart={};try{cart=normalizeCart(JSON.parse(sessionStorage.getItem('asima-cart')||'{}'),products)}catch{}
let state={q:'',category:'all',country:'',favoritesOnly:false,sort:'featured'},limit=24,view='grid',current=null;
const money=p=>p.price===null?'السعر عند الاستفسار':new Intl.NumberFormat('en-US').format(p.price);
const price=p=>`<div class="price ${p.price===null?'unavailable':''}">${money(p)}${p.price===null?'':'<small>ل.س</small>'}</div>`;
const addButton=p=>canOrder(p)?`<button class="add-to-cart" data-add="${p.id}" aria-label="أضف ${esc(p.ar)} إلى السلة"><span>+</span> أضف إلى السلة</button>`:`<div class="order-unavailable">${p.price===null?'السعر يحتاج تأكيدًا':'يلزم تأكيد تفاصيل الصنف قبل الطلب'}</div>`;
const placeholder=p=>`<div class="placeholder">${svg(p.category)}<span>صورة العبوة غير متوفرة</span></div>`;
function photo(p){return p.image?`<img src="${esc(p.image.path)}" alt="صورة مرجعية: ${esc(p.image.label)}" loading="lazy"><span class="image-label">صورة مرجعية للمنتج</span>`:placeholder(p)}
$('#totalCount').textContent=products.length;
$('#categories').innerHTML=Object.entries(cats).map(([key,name])=>`<button data-cat="${key}" class="${key==='all'?'selected':''}" aria-pressed="${key==='all'}"><span class="category-icon">${svg(key)}</span><span class="category-name">${name}</span><span class="category-count">${key==='all'?products.length:products.filter(p=>p.category===key).length}</span></button>`).join('');
[...new Set(products.map(p=>p.country))].filter(x=>x!=='غير مذكور').sort((a,b)=>a.localeCompare(b,'ar')).forEach(c=>{let o=document.createElement('option');o.value=c;o.textContent=c;$('#country').append(o)});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function storeFavorites(){try{localStorage.setItem('asima-favorites',JSON.stringify(favorites))}catch{}$('#favCount').textContent=favorites.length}
function favorite(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];storeFavorites();render(false);if(current)renderDetail(current)}
function render(reset=true){if(reset)limit=24;$('#catalog').dataset.category=state.category;const found=filterProducts(products,{...state,favorites});$('#resultCount').innerHTML=`<b>${found.length}</b> صنف ${state.q?'يطابق بحثك':'في القائمة'}${state.favoritesOnly?' · المفضلة':''}`;$('#empty').hidden=found.length!==0;$('#loadMore').hidden=found.length<=limit;$('#shownCount').textContent=found.length?`عرض ${Math.min(limit,found.length)} من ${found.length} صنف`:'';$('#clearSearch').hidden=!state.q;$('#favoritesToggle').classList.toggle('on',state.favoritesOnly);$('#favoritesToggle').setAttribute('aria-pressed',state.favoritesOnly);$('#favoritesToggle').textContent=state.favoritesOnly?'♥ عرض المفضلة':'♡ المفضلة فقط';$('#products').className='product-grid'+(view==='list'?' list':'');$('#products').innerHTML=found.slice(0,limit).map(p=>`<article class="product-card" data-category="${p.category}"><button class="card-fav ${favorites.includes(p.id)?'active':''}" data-fav="${p.id}" aria-label="${favorites.includes(p.id)?'إزالة من':'إضافة إلى'} المفضلة: ${esc(p.ar)}" aria-pressed="${favorites.includes(p.id)}">${favorites.includes(p.id)?'♥':'♡'}</button>${p.issue?'<span class="review-label">يحتاج تأكيدًا</span>':''}<button class="card-main" data-id="${p.id}" aria-label="تفاصيل ${esc(p.ar)}"><div class="product-image">${photo(p)}</div><div class="card-info"><div class="card-en" lang="en">${p.review?'≈ ':''}${esc(p.en)}</div><h3 class="card-name">${esc(p.ar)}</h3><div class="card-meta"><span>${esc(cats[p.category])}</span>${p.country==='غير مذكور'?'':`<span>${esc(p.country)}</span>`}</div><div class="card-bottom">${price(p)}<span class="details-link">التفاصيل<span>↖</span></span></div></div></button><div class="card-order">${addButton(p)}</div></article>`).join('');
$('#activeFilters').innerHTML=[state.q?`<button data-clear="q">${esc(state.q)} ×</button>`:'',state.category!=='all'?`<button data-clear="category">${cats[state.category]} ×</button>`:'',state.country?`<button data-clear="country">${esc(state.country)} ×</button>`:'',state.favoritesOnly?'<button data-clear="favorites">المفضلة ×</button>':''].join('');
$$('#categories button').forEach(b=>{b.classList.toggle('selected',b.dataset.cat===state.category);b.setAttribute('aria-pressed',b.dataset.cat===state.category)});bindImages();}
function bindImages(){$$('#products img,#detailContent img').forEach(img=>img.addEventListener('error',()=>{const p=products.find(p=>p.id===(img.closest('[data-id]')?.dataset.id||current?.id));if(p)img.parentElement.innerHTML=placeholder(p)}, {once:true}))}
function renderDetail(p){current=p;$('#detail').dataset.category=p.category;$('#detailContent').innerHTML=`<div class="detail-grid"><div class="detail-image">${p.image?`<img src="${esc(p.image.path)}" alt="${esc(p.image.label)}"><small class="pack-caption" dir="ltr" lang="en">${esc(p.image.label)}</small><small>${esc(p.image.note||'صورة مرجعية؛ قد تختلف العبوة المتوفرة في الحجم أو بلد التصنيع.')}</small>`:placeholder(p)}</div><div class="detail-info"><div class="eyebrow">${cats[p.category]} · ${p.id}</div><h2>${esc(p.ar)}</h2><p class="detail-en" lang="en" dir="ltr">${esc(p.en)}</p>${p.review?'<p class="review-name">الاسم الإنجليزي للبحث فقط؛ يحتاج مطابقة مع العبوة الأصلية.</p>':''}${price(p)}<dl><dt>العملة</dt><dd>الليرة السورية — SYP</dd><dt>المنشأ بالقائمة</dt><dd>${esc(p.country)}</dd><dt>حالة التوفر</dt><dd>مُدرج في قائمة المورد؛ يُرجى التأكيد</dd></dl><div class="detail-actions">${addButton(p)}<button class="primary" id="copyProduct">نسخ اسم الصنف والسعر</button><button class="outline" id="detailFavorite">${favorites.includes(p.id)?'♥ محفوظ':'♡ حفظ'}</button></div></div></div>${p.issue?`<div class="detail-warning">${esc(p.issue)}</div>`:''}<details class="source-details"><summary>تفاصيل القائمة ومصدر الصورة</summary><p>النص المنقول من قائمة المورد: <b>${esc(p.original)}</b></p>${p.image?`<p>العبوة الظاهرة: <span dir="ltr">${esc(p.image.label)}</span></p><a href="${esc(p.image.source)}" target="_blank" rel="noopener noreferrer">عرض مصدر الصورة ↗</a>`:'<p>لم تُرفق صورة مؤكدة لهذا الصنف. تُضاف صورة العبوة بعد مطابقتها.</p>'}</details><p class="detail-disclaimer">السعر مرجعي من القائمة، وصلاحيته يوم واحد بحسب المورد. تأكد من السعر والعبوة والتوفر قبل الطلب. لا تعتمد على الصورة لتحديد الدواء أو الجرعة.</p>`;$('#copyProduct').onclick=async()=>{const text=`${p.ar}\n${p.en}\n${money(p)}${p.price===null?'':' ل.س'}\nمستودع العاصمة — يرجى تأكيد السعر والتوفر.`;try{await navigator.clipboard.writeText(text);toast('تم نسخ بيانات الصنف')}catch{toast('تعذّر النسخ التلقائي. يمكنك تحديد البيانات ونسخها.')}};$('#detailFavorite').onclick=()=>favorite(p.id);const add=$('#detailContent [data-add]');if(add)add.onclick=()=>addToCart(add.dataset.add);bindImages()}
function openDetail(id){const p=products.find(p=>p.id===id);if(!p)return;renderDetail(p);if(!$('#detail').open)$('#detail').showModal();history.replaceState(null,'',`#${p.id}`)}
$('#products').onclick=e=>{const add=e.target.closest('[data-add]');if(add){addToCart(add.dataset.add);return}const f=e.target.closest('[data-fav]');if(f){favorite(f.dataset.fav);return}const b=e.target.closest('[data-id]');if(b)openDetail(b.dataset.id)};
$('#detail .dialog-close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});$('#detail').addEventListener('close',()=>{current=null;history.replaceState(null,'','#catalog')});
$('#search').oninput=e=>{state.q=e.target.value;render()};$('#clearSearch').onclick=()=>{state.q='';$('#search').value='';render();$('#search').focus()};$('#searchForm').onsubmit=e=>{e.preventDefault();state.q=$('#search').value;render();$('#catalog').scrollIntoView({behavior:'smooth'})};
$$('[data-query]').forEach(b=>b.onclick=()=>{state.q=b.dataset.query;state.category='all';state.country='';state.favoritesOnly=false;$('#country').value='';$('#search').value=state.q;render();$('#catalog').scrollIntoView({behavior:'smooth'})});
$('#categories').onclick=e=>{const b=e.target.closest('[data-cat]');if(b){state.category=b.dataset.cat;render()}};$('#country').onchange=e=>{state.country=e.target.value;render()};$('#sort').onchange=e=>{state.sort=e.target.value;render()};$('#favoritesToggle').onclick=()=>{state.favoritesOnly=!state.favoritesOnly;render()};$('#navFavorites').onclick=()=>{state.q='';state.category='all';state.country='';state.favoritesOnly=true;$('#search').value='';$('#country').value='';render();$('#catalog').scrollIntoView({behavior:'smooth'})};$('#loadMore').onclick=()=>{limit+=24;render(false)};
$('#activeFilters').onclick=e=>{const key=e.target.closest('[data-clear]')?.dataset.clear;if(!key)return;if(key==='q'){state.q='';$('#search').value=''}if(key==='category')state.category='all';if(key==='country'){state.country='';$('#country').value=''}if(key==='favorites')state.favoritesOnly=false;render()};
$('#reset').onclick=()=>{state={q:'',category:'all',country:'',favoritesOnly:false,sort:'featured'};$('#search').value='';$('#country').value='';$('#sort').value='featured';render()};
for(const [id,type]of[['gridView','grid'],['listView','list']])$('#'+id).onclick=()=>{view=type;$('#gridView').classList.toggle('selected',type==='grid');$('#listView').classList.toggle('selected',type==='list');render(false)};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail').open&&!$('#cartDialog').open){e.preventDefault();$('#search').focus()}});
const heroNames=['Osteocare','Panadol','Feroglobin'];const hero=heroNames.map(name=>products.find(p=>p.en.startsWith(name)&&p.image)).filter(Boolean);$('#showcase').innerHTML=hero.map(p=>`<img src="${esc(p.image.path)}" alt="" onerror="this.hidden=true">`).join('');

function saveCart(){cart=normalizeCart(cart,products);try{sessionStorage.setItem('asima-cart',JSON.stringify(cart))}catch{}updateCartBadge();}
function updateCartBadge(){const s=cartSummary(cart,products);$$('.cart-badge').forEach(el=>el.textContent=s.count);$('#cartDock').hidden=s.count===0;document.body.classList.toggle('has-cart',s.count>0);$('#dockCount').textContent=`${s.count} قطعة في السلة`;$('#dockTotal').textContent=new Intl.NumberFormat('en-US').format(s.total)+' ل.س';$$('[data-open-cart]').forEach(b=>b.setAttribute('aria-label',`فتح سلة الطلبات — ${s.count} قطعة`));}
function addToCart(id){const p=products.find(p=>p.id===id);if(!canOrder(p))return;cart[id]=Math.min(99,(cart[id]||0)+1);saveCart();toast('أُضيف الصنف إلى السلة');}
function renderCart(){saveCart();const s=cartSummary(cart,products);if(!s.items.length){$('#cartContent').innerHTML='<div class="cart-empty"><span>🛒</span><h3>سلتك بانتظار اختياراتك</h3><p>أضف الأصناف من القائمة، ثم أرسل طلبك عبر واتساب.</p><button class="primary" id="continueShopping">تصفّح المنتجات</button></div>';$('#continueShopping').onclick=()=>$('#cartDialog').close();return;}
const parts=buildWhatsAppParts(cart,products);$('#cartContent').innerHTML=`<div class="cart-items">${s.items.map(({product:p,qty})=>`<div class="cart-row" data-category="${p.category}"><div class="cart-thumb">${p.image?`<img src="${esc(p.image.path)}" alt="" onerror="this.hidden=true">`:svg(p.category)}</div><div class="cart-item-info"><h3>${esc(p.ar)}</h3><p lang="en" dir="ltr">${esc(p.en)}</p><small>${money(p)} ل.س / قطعة</small><div class="quantity"><button data-qty="${p.id}" data-step="-1" aria-label="تقليل كمية ${esc(p.ar)}" ${qty<=1?'disabled':''}>−</button><input data-quantity="${p.id}" aria-label="كمية ${esc(p.ar)}" type="number" min="1" max="99" step="1" value="${qty}"><button data-qty="${p.id}" data-step="1" aria-label="زيادة كمية ${esc(p.ar)}" ${qty>=99?'disabled':''}>+</button></div></div><div class="cart-row-end"><button data-remove="${p.id}" aria-label="حذف ${esc(p.ar)} من السلة">×</button><strong>${new Intl.NumberFormat('en-US').format(qty*p.price)} <small>ل.س</small></strong></div></div>`).join('')}</div><div class="cart-total"><span>الإجمالي التقديري <small>${s.items.length} صنف · ${s.count} قطعة</small></span><b>${new Intl.NumberFormat('en-US').format(s.total)} <small>ل.س</small></b></div><p class="cart-note">الإجمالي لا يشمل التوصيل. يُؤكّد المستودع الأسعار والتوفر وأي وصفة مطلوبة قبل تجهيز الطلب.</p><div class="checkout-recipient"><svg viewBox="0 0 24 24" aria-hidden="true"><use href="#whatsapp-icon"/></svg><span>رقم واتساب المعتمد للطلبات</span><b dir="ltr">+963967765704</b></div>${parts.length>1?`<p class="cart-split">طلبك طويل؛ قُسّم إلى ${parts.length} رسائل. افتح كل جزء وأرسله في واتساب.</p>`:''}<div class="checkout-links">${parts.map((part,i)=>`<a class="whatsapp-checkout" href="${esc(part.url)}" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><use href="#whatsapp-icon"/></svg>${parts.length===1?'فتح الطلب في واتساب':`فتح الجزء ${i+1} من ${parts.length} في واتساب`}<span>↗</span></a>`).join('')}</div><p class="cart-send-note">ستفتح رسالة جاهزة. اضغط «إرسال» داخل واتساب لإتمام إرسالها.</p><button class="cart-clear" id="clearCart">إفراغ السلة</button>`;
$('#clearCart').onclick=()=>{cart={};renderCart();toast('أُفرغت السلة')};}
$$('[data-open-cart]').forEach(b=>b.onclick=()=>{if($('#detail').open)$('#detail').close();renderCart();$('#cartDialog').showModal()});$('#closeCart').onclick=()=>$('#cartDialog').close();$('#cartDialog').addEventListener('click',e=>{if(e.target===$('#cartDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#cartContent').onclick=e=>{const rem=e.target.closest('[data-remove]');if(rem){delete cart[rem.dataset.remove];renderCart();return}const step=e.target.closest('[data-qty]');if(step){cart[step.dataset.qty]=Math.min(99,Math.max(1,(cart[step.dataset.qty]||1)+Number(step.dataset.step)));renderCart()}};$('#cartContent').onchange=e=>{const input=e.target.closest('[data-quantity]');if(input){const n=Number(input.value);cart[input.dataset.quantity]=Number.isFinite(n)?Math.min(99,Math.max(1,Math.floor(n))):1;renderCart()}};
updateCartBadge();

storeFavorites();render();if(location.hash.startsWith('#MED-'))openDetail(location.hash.slice(1));
})();
